mapper.select:
select dpr.id as dprId, bmc.cid as cid, dpr.api_code as apiCode, bmc.short_name as shortName, pkg.id as pkgId, pkg.package_name as packageName, dpt.discreet_number as discreetNumber, (SELECT COUNT(*) FROM b_xiecheng_colliding_data_rob WHERE package_id = pkg.id AND is_delete = 0) as remainingNumber, dpr.colliding_switch as collidingSwitch, pkg.priority as priority, dpr.colliding_back_number as collidingBackNumber, dpt.task_start_time as taskStartTime, dpr.colliding_start_time as collidingStartTime, dpr.colliding_end_time as collidingEndTime, dpr.create_time as createTime, dpr.update_time as updateTime from b_xiecheng_colliding_data_package_rule dpr left join b_marketing_customer bmc on bmc.api_code = dpr.api_code and bmc.status = 1 left join b_xiecheng_colliding_data_package pkg on pkg.id = dpr.package_id and pkg.is_delete = 0 left join b_xiecheng_colliding_data_process_task dpt on dpt.id = dpr.colliding_data_task_id and dpt.is_delete = 0 where dpr.is_delete = 0
and pkg.package_name like '%${listParam.keyword}%'
and dpr.api_code = #{listParam.apiCode}
and dpr.colliding_switch = #{listParam.collidingSwitch}
AND (dpr.colliding_start_time BETWEEN #{listParam.collidingStartTime} AND #{listParam.collidingEndTime} OR dpr.colliding_end_time BETWEEN #{listParam.collidingStartTime} AND #{listParam.collidingEndTime})
